        sport=('Clubs are looking at free agents.', 'List the first name, last name and position of players with no team. Sort by last name, then first name.', ['first_name', 'last_name', 'position'], 'SELECT first_name, last_name, position\nFROM players\nWHERE team_id IS NULL\nORDER BY last_name, first_name;'),
        fashion=('Stores want to see December walk-in sales, where no customer was recorded.', 'List the sale id, store id and sale date of sales from 2025-12-01 onwards with no customer. Sort by sale date, then sale id.', ['sale_id', 'store_id', 'sale_date'], "SELECT sale_id, store_id, sale_date\nFROM sales\nWHERE customer_id IS NULL\n  AND sale_date >= '2025-12-01'\nORDER BY sale_date, sale_id;"),
        politics=('The commission is publishing a list of independent candidates.', 'List the first name, last name and gender of candidates with no party. Sort by last name, then first name.', ['first_name', 'last_name', 'gender'], 'SELECT first_name, last_name, gender\nFROM candidates\nWHERE party_id IS NULL\nORDER BY last_name, first_name;'),
