        fashion=('The Accra store is preparing loyalty cards.', "For customers in 'Accra', return full_name (first and last name joined by a space), email and tier, showing 'No tier' when the loyalty tier is blank. Sort by full name.",
                 ['full_name', 'email', 'tier'], "SELECT CONCAT(first_name, ' ', last_name) AS full_name,\n       email,\n       COALESCE(loyalty_tier, 'No tier') AS tier\nFROM customers\nWHERE city = 'Accra'\nORDER BY full_name;"),
