  dict(level='Hard', concepts=['Arithmetic', 'ROUND', 'CASE'], order=True,
       hint2='Calculate the new column with arithmetic, wrap it in ROUND(value, 2), and add a CASE label. Multiply by 100.0, not 100, when you need a percentage.',
       explain='The calculation runs row by row, ROUND keeps it readable, and CASE adds a label on top. Using 100.0 keeps the maths in decimals instead of whole numbers.',
       v=dict(
        sales=('Finance is auditing heavily discounted order lines.', 'For order items with a discount of at least 0.10, return order item id, order id, line_total (quantity x unit price x (1 - discount), rounded to 2 decimals) and discount_level: \'Deep\' when the discount is 0.20 or more, otherwise \'Standard\'. Show the 15 largest line totals, largest first, then order item id.',
               ['order_item_id', 'order_id', 'line_total', 'discount_level'], "SELECT order_item_id, order_id,\n       ROUND(quantity * unit_price * (1 - discount), 2) AS line_total,\n       CASE WHEN discount >= 0.20 THEN 'Deep' ELSE 'Standard' END AS discount_level\nFROM order_items\nWHERE discount >= 0.10\nORDER BY line_total DESC, order_item_id\nLIMIT 15;"),
        sport=("Team 1's analyst is reviewing home results.", "For team 1's home matches in the 2025 season, return match id, match date, total_goals (home + away) and result: 'Win' when home goals are higher, 'Draw' when equal, otherwise 'Loss'. Sort by match date.",
               ['match_id', 'match_date', 'total_goals', 'result'], "SELECT match_id, match_date,\n       home_goals + away_goals AS total_goals,\n       CASE\n         WHEN home_goals > away_goals THEN 'Win'\n         WHEN home_goals = away_goals THEN 'Draw'\n         ELSE 'Loss'\n       END AS result\nFROM matches\nWHERE home_team_id = 1\n  AND season = 2025\nORDER BY match_date;"),
        fashion=('The bag buyer wants margins on the range.', "For 'Bags', return product name, margin_pct ((retail - cost) x 100 / retail, rounded to 1 decimal) and margin_band: 'High' at 60 or more, 'Medium' at 50 or more, otherwise 'Low'. Highest margin first, then product name.",
                 ['product_name', 'margin_pct', 'margin_band'], "SELECT product_name,\n       ROUND((retail_price - cost_price) * 100.0 / retail_price, 1) AS margin_pct,\n       CASE\n         WHEN (retail_price - cost_price) * 100.0 / retail_price >= 60 THEN 'High'\n         WHEN (retail_price - cost_price) * 100.0 / retail_price >= 50 THEN 'Medium'\n         ELSE 'Low'\n       END AS margin_band\nFROM products\nWHERE category = 'Bags'\nORDER BY margin_pct DESC, product_name;"),
        politics=("An analyst is reading Aldoria Opinion's December 2025 poll.", "For polls by 'Aldoria Opinion' that ended in December 2025, return party id, vote share, respondents (vote share x sample size / 100, rounded to a whole number) and support_level: 'Major' at 20% or more, 'Mid' at 8% or more, otherwise 'Minor'. Highest vote share first.",
                  ['party_id', 'vote_share_pct', 'respondents', 'support_level'], "SELECT party_id, vote_share_pct,\n       ROUND(vote_share_pct * sample_size / 100) AS respondents,\n       CASE\n         WHEN vote_share_pct >= 20 THEN 'Major'\n         WHEN vote_share_pct >= 8 THEN 'Mid'\n         ELSE 'Minor'\n       END AS support_level\nFROM polls\nWHERE pollster = 'Aldoria Opinion'\n  AND fieldwork_end >= '2025-12-01'\nORDER BY vote_share_pct DESC;"),
        finance=('Treasury is estimating interest on this year\'s SME loans.', "For 'SME Working Capital' loans disbursed on or after 2025-01-01, return loan id, principal, total_interest (principal x rate / 100 x tenor months / 12, rounded to 2 decimals) and size: 'Large' at a principal of 2,000,000 or more, otherwise 'Standard'. Largest interest first, then loan id.",
                 ['loan_id', 'principal', 'total_interest', 'size'], "SELECT loan_id, principal,\n       ROUND(principal * interest_rate_pct / 100 * tenor_months / 12, 2) AS total_interest,\n       CASE WHEN principal >= 2000000 THEN 'Large' ELSE 'Standard' END AS size\nFROM loans\nWHERE product = 'SME Working Capital'\n  AND disbursed_date >= '2025-01-01'\nORDER BY total_interest DESC, loan_id;"),
        healthcare=('Pharmacy is reviewing Atorvastatin costs.', "For 'Atorvastatin' prescriptions, return prescription id, days supplied, cost_per_day (cost / days supplied, rounded to 2 decimals) and supply_type: 'Long-term' at 60 days or more, 'Course' at 14 or more, otherwise 'Short'. Highest cost per day first, then prescription id.",
                    ['prescription_id', 'days_supplied', 'cost_per_day', 'supply_type'], "SELECT prescription_id, days_supplied,\n       ROUND(cost / days_supplied, 2) AS cost_per_day,\n       CASE\n         WHEN days_supplied >= 60 THEN 'Long-term'\n         WHEN days_supplied >= 14 THEN 'Course'\n         ELSE 'Short'\n       END AS supply_type\nFROM prescriptions\nWHERE drug_name = 'Atorvastatin'\nORDER BY cost_per_day DESC, prescription_id;"))),
